// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address, a single to address encoded as uint160, and a value v
    function testFuzz_property(address from, uint160 toAddrRaw, uint256 v, uint256 tosLenSeed) public {
        // keep array length small but allow 1 (admissible domain requires >0)
        uint256 tosLen = 1 + (tosLenSeed % 3); // 1..3
        address to = address(uint160(toAddrRaw));

        // deploy a recorder that implements the transferFrom signature and records calls
        Recorder r = new Recorder();

        // build tos array
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) tos[i] = to;

        // ensure recorder has some balance so call can carry value if needed (not required here)
        vm.deal(address(this), 1 ether);

        // call transfer on c; c will call recorder via low-level call with a selector
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant to check: the reference implementation ALWAYS invoked the callee using
        // selector(bytes4(keccak256("transferFrom(address,address,uint256)"))). The recorder
        // decodes and records calls that match that selector; if the mutant used a different
        // selector (transfer(address,address,uint256)) the recorder's recordedCount will be zero
        // or its decoded args won't match. We assert that either the call reverted (ok==false),
        // or if it succeeded the recorder has recorded exactly tosLen calls with the expected
        // decoded arguments matching what we passed.
        if (ok) {
            // when transfer returns successfully, the correct contract must have invoked the
            // transferFrom selector on the callee exactly tosLen times and recorded arguments
            // must match the inputs. This is a universal property of the reference and is
            // violated by the mutant for some inputs (the selector differs).
            assertTrue(r.recordedCount() == tosLen && r.lastFrom() == from && r.lastValue() == v && r.lastTo() == to);
        } else {
            // If the top-level call reverted, we still accept it as admissible behavior;
            // just assert that this is a valid observed outcome (ok == false). The single
            // assertTrue must hold for all inputs on the reference; for the reference it will
            // either succeed and recorder observed the calls, or revert — both are allowed.
            assertTrue(ok == false);
        }
    }
}

// Recorder declares the exact transferFrom signature so that properly-formed calls
// using that selector get ABI-decoded and recorded. If the caller uses a different
// selector (the mutant does), those calls won't match this function signature and
// will not be decoded into this function; fallback will record a generic hit but not
// the decoded args. We only record decoded invocations here.
contract Recorder {
    uint public recorded;
    address public _lastFrom;
    address public _lastTo;
    uint public _lastValue;

    // this matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        recorded += 1;
        _lastFrom = from;
        _lastTo = to;
        _lastValue = value;
        return true;
    }

    // fallback records that a non-matching selector was called
    fallback() external payable {
        // do nothing else; fallback ensures mutant calls that use a different selector
        // do not get decoded into transferFrom and thus do not increment `recorded`.
    }

    // getters to satisfy the test's reads
    function recordedCount() external view returns (uint) { return recorded; }
    function lastFrom() external view returns (address) { return _lastFrom; }
    function lastTo() external view returns (address) { return _lastTo; }
    function lastValue() external view returns (uint) { return _lastValue; }
}
